-- ============================================================
-- Osman Bey 1299 Scenario - start of game
-- Founds the cities each great power held in 1299 and removes
-- their starting settlers. Runs once, on the first turn.
-- Generated by tools/build_mod.py.
-- ============================================================
print("Osman Bey 1299: OB1299_Scenario.lua loaded")

-- {name, x, y, population}; the first city is the capital
local SCENARIO_CITIES = {
	["CIVILIZATION_BYZANTIUM"] = {{"Constantinople", 53, 60, 8}, {"Thessalonica", 38, 59, 5}, {"Adrianople", 47, 62, 4}, {"Philadelphia", 53, 50, 3}, {"Mistra", 37, 45, 3}},
	["CIVILIZATION_MONGOL"] = {{"Tabriz", 94, 49, 8}, {"Baghdad", 91, 33, 6}, {"Sultaniyya", 97, 43, 4}, {"Mosul", 88, 43, 4}, {"Erzurum", 85, 56, 3}, {"Sivas", 75, 55, 4}, {"Isfahan", 101, 31, 5}},
	["CIVILIZATION_EGYPT"] = {{"Cairo", 60, 26, 9}, {"Alexandria", 56, 28, 5}, {"Damascus", 74, 34, 6}, {"Aleppo", 76, 42, 5}, {"Jerusalem", 71, 29, 3}, {"Qus", 64, 17, 3}},
	["CIVILIZATION_VENICE"] = {{"Venice", 19, 73, 6}, {"Candia", 43, 40, 3}, {"Zara", 24, 69, 2}},
	["CIVILIZATION_AUSTRIA"] = {{"Vienna", 26, 78, 5}, {"Graz", 24, 76, 3}},
	["CIVILIZATION_POLAND"] = {{"Krakow", 31, 82, 4}},
	["CIVILIZATION_MOROCCO"] = {{"Fez", 1, 36, 6}, {"Tangier", 0, 41, 3}, {"Sijilmasa", 1, 28, 2}},
}

-- Extra buildings for some cities (Theodosian Walls of Constantinople...)
local CITY_BUILDINGS = {
	["Constantinople"] = {"BUILDING_WALLS", "BUILDING_CASTLE"},
	["Tabriz"] = {"BUILDING_WALLS"},
	["Cairo"] = {"BUILDING_WALLS"},
	["Venice"] = {"BUILDING_WALLS"},
	["Vienna"] = {"BUILDING_WALLS"},
	["Damascus"] = {"BUILDING_WALLS"},
	["Thessalonica"] = {"BUILDING_WALLS"},
}

local function IsOurMap()
	local sMap = PreGame.GetMapScript() or ""
	return string.find(sMap, "OB_Ottoman1299", 1, true) ~= nil
end

local function CanPlaceCity(plot, iPlayer)
	if plot == nil or plot:IsWater() or plot:IsMountain() or plot:IsImpassable() or plot:IsCity() then return false end
	local iOwner = plot:GetOwner()
	if iOwner ~= -1 and iOwner ~= iPlayer then return false end
	if plot:GetNumUnits() > 0 then
		for i = 0, plot:GetNumUnits() - 1 do
			local u = plot:GetUnit(i)
			if u ~= nil and u:GetOwner() ~= iPlayer then return false end
		end
	end
	local x, y = plot:GetX(), plot:GetY()
	for dx = -3, 3 do
		for dy = -3, 3 do
			local p = Map.GetPlot(x + dx, y + dy)
			if p ~= nil and Map.PlotDistance(x, y, p:GetX(), p:GetY()) <= 2 and p:IsCity() then return false end
		end
	end
	-- keep away from the starting positions of other players
	for i = 0, GameDefines.MAX_CIV_PLAYERS - 1 do
		local pOther = Players[i]
		if i ~= iPlayer and pOther ~= nil and pOther:IsAlive() then
			local sp = pOther:GetStartingPlot()
			if sp ~= nil and Map.PlotDistance(x, y, sp:GetX(), sp:GetY()) < 3 then return false end
		end
	end
	return true
end

local function FindCityPlot(tx, ty, iPlayer)
	for radius = 0, 4 do
		local best, bestScore = nil, -1
		for dx = -radius - 1, radius + 1 do
			for dy = -radius - 1, radius + 1 do
				local p = Map.GetPlot(tx + dx, ty + dy)
				if p ~= nil and Map.PlotDistance(tx, ty, p:GetX(), p:GetY()) == radius and CanPlaceCity(p, iPlayer) then
					local score = 10
					if p:IsRiver() then score = score + 3 end
					if p:IsCoastalLand() then score = score + 2 end
					if p:IsHills() then score = score + 1 end
					if score > bestScore then best, bestScore = p, score end
				end
			end
		end
		if best ~= nil then return best end
	end
	return nil
end

local function SetUpPlayer(iPlayer, cities)
	local pPlayer = Players[iPlayer]
	if pPlayer:GetNumCities() > 0 then return end
	local nFounded = 0
	for i, c in ipairs(cities) do
		local tx, ty = c[2], c[3]
		if i == 1 then
			-- The capital goes on the start plot chosen by the map script.
			local sp = pPlayer:GetStartingPlot()
			if sp ~= nil then tx, ty = sp:GetX(), sp:GetY() end
		end
		local plot = FindCityPlot(tx, ty, iPlayer)
		if plot ~= nil then
			local pCity = pPlayer:InitCity(plot:GetX(), plot:GetY())
			if pCity ~= nil then
				nFounded = nFounded + 1
				pCity:SetName(c[1])
				if c[4] > 1 then pCity:SetPopulation(c[4], true) end
				if nFounded == 1 and not pCity:IsCapital() and GameInfoTypes.BUILDING_PALACE ~= nil then
					pCity:SetNumRealBuilding(GameInfoTypes.BUILDING_PALACE, 1)
				end
				for _, b in ipairs(CITY_BUILDINGS[c[1]] or {}) do
					local iB = GameInfoTypes[b]
					if iB ~= nil then pCity:SetNumRealBuilding(iB, 1) end
				end
			end
		else
			print("Osman Bey 1299: no room for " .. c[1])
		end
	end
	if nFounded > 0 then
		-- The cities replace the starting settlers.
		local iSettler = GameInfoTypes.UNITCLASS_SETTLER
		local toKill = {}
		for pUnit in pPlayer:Units() do
			if pUnit:GetUnitClassType() == iSettler then table.insert(toKill, pUnit) end
		end
		for _, pUnit in ipairs(toKill) do pUnit:Kill(true, -1) end
	end
	print("Osman Bey 1299: player " .. iPlayer .. " starts with " .. nFounded .. " cities")
end

local function SetUpScenario()
	if Game.GetGameTurn() > 0 or not IsOurMap() then return end
	for iPlayer = 0, GameDefines.MAX_MAJOR_CIVS - 1 do
		local pPlayer = Players[iPlayer]
		if pPlayer ~= nil and pPlayer:IsAlive() then
			local info = GameInfo.Civilizations[pPlayer:GetCivilizationType()]
			local cities = info and SCENARIO_CITIES[info.Type]
			if cities ~= nil then
				local ok, err = pcall(SetUpPlayer, iPlayer, cities)
				if not ok then print("Osman Bey 1299: setup error for player " .. iPlayer .. ": " .. tostring(err)) end
			end
		end
	end
end

SetUpScenario()
